/* the Controls buttons: recommended / original key bindings in the mode configs */
#include "lc_settings.h"
#include "lc_test.h"
#include "lc_test_util.h"
#include <stdlib.h>

static const char *config =
	"// generated by quake, do not modify\n"
	"unbindall\n"
	"bind TAB \"+info\"\n"
	"bind SPACE \"+use\"\n"
	"BIND MOUSE2 \"+forward\"\n"
	"unbind q\n"
	"seta name \"Munro\"\n"
	"seta r_fullscreen \"1\"\r\n"
	"  bind\tF5 \"save quik*\"\n"
	"seta bindings_note \"bind x\"";		/* no newline at the end */

static int Count( const char *text, const char *what )
{
	int n = 0;
	for ( ; ( text = strstr( text, what ) ) != NULL; text++ )
		n++;
	return n;
}

static void TestRewrite( void )
{
	char *sp = lc_controls_rewrite( config, 0, LC_CONTROLS_RECOMMENDED );
	char *hm = lc_controls_rewrite( config, 1, LC_CONTROLS_RECOMMENDED );
	char *orig = lc_controls_rewrite( config, 0, LC_CONTROLS_ORIGINAL );
	char *fresh = lc_controls_rewrite( NULL, 1, LC_CONTROLS_RECOMMENDED );

	/* other lines kept, in order, with their line ends */
	CHECK( strstr( sp, "// generated by quake, do not modify\nseta name \"Munro\"\nseta r_fullscreen \"1\"\r\n"
		"seta bindings_note \"bind x\"\nunbindall\n" ) == sp );
	CHECK( Count( sp, "unbindall" ) == 1 );
	CHECK( !strstr( sp, "+forward\"\nbind MOUSE3" ) );
	CHECK( strstr( sp, "bind MOUSE2 \"+altattack\"\n" ) != NULL );
	CHECK( strstr( sp, "bind SPACE \"+moveup\"\n" ) != NULL );
	CHECK( strstr( sp, "bind e \"+use\"\n" ) != NULL );
	CHECK( strstr( sp, "bind q \"+analysis\"\n" ) != NULL );
	CHECK( strstr( sp, "bind F3 \"ui_teamOrders\"\n" ) != NULL );
	CHECK( strstr( sp, "bind F5 \"save quik*\"\n" ) != NULL );
	CHECK( strstr( sp, "bind \\ \"+mlook\"\n" ) != NULL );
	CHECK( !strstr( sp, "messagemode3" ) );
	CHECK( strstr( hm, "bind g \"messagemode3\"\n" ) != NULL );
	CHECK( strstr( hm, "bind h \"messagemode4\"\n" ) != NULL );
	CHECK( strstr( hm, "bind f \"+button3\"\n" ) != NULL );
	CHECK( !strstr( hm, "+analysis" ) && !strstr( hm, "quik" ) );

	CHECK( lc_controls_is_recommended( sp, 0 ) );
	CHECK( lc_controls_is_recommended( hm, 1 ) );
	CHECK( !lc_controls_is_recommended( sp, 1 ) );		/* the other mode's set */
	CHECK( !lc_controls_is_recommended( config, 0 ) );
	CHECK( lc_controls_is_recommended( fresh, 1 ) );
	CHECK( !strncmp( fresh, "unbindall\n", 10 ) );

	/* original: no bind lines at all, so default.cfg's apply */
	CHECK_STR( orig, "// generated by quake, do not modify\nseta name \"Munro\"\nseta r_fullscreen \"1\"\r\n"
		"seta bindings_note \"bind x\"\n" );
	CHECK( !lc_controls_is_recommended( orig, 0 ) );

	/* an extra binding is no longer the recommended set; key names in any case are */
	{
		size_t n = strlen( sp );
		char *more = malloc( n + 64 ), *upper;
		strcpy( more, sp );
		strcat( more, "bind F9 \"quickload\"\n" );
		CHECK( !lc_controls_is_recommended( more, 0 ) );
		upper = lc_controls_rewrite( "", 0, LC_CONTROLS_RECOMMENDED );
		{
			char *k = strstr( upper, "bind w " );
			k[5] = 'W';
		}
		CHECK( lc_controls_is_recommended( upper, 0 ) );
		free( more );
		free( upper );
	}
	free( sp );
	free( hm );
	free( orig );
	free( fresh );
}

static void TestApply( void )
{
	const char *dir = tu_dir( "controls" );
	char sp[LC_MAX_PATH], hm[LC_MAX_PATH], err[256];
	char *text;
	size_t len;

	lc_config_path( dir, 0, sp, sizeof( sp ) );
	lc_config_path( dir, 1, hm, sizeof( hm ) );

	/* no configs yet: original leaves them missing, recommended writes both */
	CHECK( lc_controls_apply( dir, LC_CONTROLS_ORIGINAL, err, sizeof( err ) ) );
	CHECK( !lc_is_file( sp ) && !lc_is_file( hm ) );
	CHECK( !lc_controls_recommended_in_use( dir ) );
	tu_text( dir, "efspconfig.cfg", config );
	CHECK( lc_controls_apply( dir, LC_CONTROLS_RECOMMENDED, err, sizeof( err ) ) );
	CHECK( lc_controls_recommended_in_use( dir ) );
	text = lc_read_file( sp, &len );
	CHECK( text && strstr( text, "seta name \"Munro\"\n" ) && strstr( text, "bind q \"+analysis\"\n" ) );
	free( text );
	text = lc_read_file( hm, &len );
	CHECK( text && strstr( text, "bind h \"messagemode4\"\n" ) );
	free( text );

	/* the files keep their times: lc_gfx_load picks the newer config by them */
	CHECK( lc_file_set_mtime( sp, 1000000000 ) && lc_file_set_mtime( hm, 1500000000 ) );
	CHECK( lc_controls_apply( dir, LC_CONTROLS_ORIGINAL, err, sizeof( err ) ) );
	CHECK( lc_file_mtime( sp ) == 1000000000 && lc_file_mtime( hm ) == 1500000000 );
	CHECK( !lc_controls_recommended_in_use( dir ) );
	text = lc_read_file( sp, &len );
	CHECK( text && !strstr( text, "\nbind " ) && !strstr( text, "unbind" ) && strstr( text, "seta name \"Munro\"\n" ) );
	free( text );
	text = lc_read_file( hm, &len );
	CHECK( text && !strstr( text, "bind" ) );
	free( text );
}

/* a mod folder's own config (the engine saves one after a server's fs_game) is left alone */
static void TestModFoldersUntouched( void )
{
	const char *root = tu_dir( "controls-root" );
	const char *modText = "unbindall\nbind SPACE \"+use\"\nseta name \"Munro\"\n";
	char base[LC_MAX_PATH], mod[LC_MAX_PATH], empty[LC_MAX_PATH], path[LC_MAX_PATH], err[256];
	char *text;
	size_t len;

	lc_path_join( base, sizeof( base ), root, "baseEF" );
	lc_path_join( mod, sizeof( mod ), root, "tw2" );
	lc_path_join( empty, sizeof( empty ), root, "nanoef" );
	lc_mkdir_p( base );
	lc_mkdir_p( mod );
	lc_mkdir_p( empty );
	tu_text( mod, "hmconfig.cfg", modText );

	CHECK( lc_controls_apply( base, LC_CONTROLS_RECOMMENDED, err, sizeof( err ) ) );
	CHECK( lc_controls_recommended_in_use( base ) );
	CHECK( lc_controls_apply( base, LC_CONTROLS_ORIGINAL, err, sizeof( err ) ) );
	lc_path_join( path, sizeof( path ), mod, "hmconfig.cfg" );
	text = lc_read_file( path, &len );
	CHECK_STR( text, modText );
	free( text );
	lc_path_join( path, sizeof( path ), mod, "efspconfig.cfg" );
	CHECK( !lc_is_file( path ) );
	lc_path_join( path, sizeof( path ), empty, "hmconfig.cfg" );
	CHECK( !lc_is_file( path ) );
}

int main( void )
{
	TestRewrite( );
	TestApply( );
	TestModFoldersUntouched( );
	return TEST_DONE( );
}
